"use client";

import { useState, useEffect, useMemo, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';
import { Navbar } from '@/components/navbar';
import { Footer } from '@/components/footer';
import { CATEGORIES, PRODUCTS } from '@/lib/products';
import { cn } from '@/lib/utils';

function CatalogContent() {
  const searchParams = useSearchParams();
  const categoryParam = searchParams.get('category') || 'all';
  const [activeCategory, setActiveCategory] = useState(categoryParam);

  // Follow ?category= changes from links elsewhere on the site (e.g. the footer).
  useEffect(() => setActiveCategory(categoryParam), [categoryParam]);

  const filteredProducts = useMemo(() => {
    if (activeCategory === 'all') return PRODUCTS;
    return PRODUCTS.filter(p => p.category === activeCategory);
  }, [activeCategory]);

  return (
    <div className="container py-16">
      <header className="mb-14 text-center">
        <p className="text-[11px] font-headline uppercase tracking-[0.3em] text-accent mb-3">The Collection</p>
        <h1 className="font-display text-4xl md:text-5xl mb-4">Shop All Pieces</h1>
        <div className="h-px w-14 bg-accent mx-auto" />
        <div className="flex flex-wrap justify-center gap-6 mt-10">
          {CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              className={cn(
                "text-[11px] font-headline uppercase tracking-[0.25em] pb-1 border-b transition-all",
                activeCategory === cat.id
                  ? "text-foreground border-accent"
                  : "text-muted-foreground border-transparent hover:text-foreground"
              )}
            >
              {cat.label}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-x-6 gap-y-12">
        {filteredProducts.map((product) => (
          <Link key={product.id} href={`/products/${product.id}`} className="group">
            <div className="relative aspect-[4/5] overflow-hidden bg-muted mb-4">
              <Image
                src={product.images[0]}
                alt={product.name}
                fill
                sizes="(min-width: 1024px) 25vw, (min-width: 768px) 33vw, 50vw"
                className="object-cover transition-transform duration-500 group-hover:scale-105"
              />
            </div>
            <h3 className="font-display text-lg leading-tight mb-1 group-hover:text-accent transition-colors">{product.name}</h3>
            <p className="text-xs text-muted-foreground">£{product.price.toFixed(2)}</p>
          </Link>
        ))}
      </div>

      {filteredProducts.length === 0 && (
        <div className="py-20 text-center">
          <p className="text-muted-foreground">No pieces found in this category.</p>
        </div>
      )}
    </div>
  );
}

export default function ProductsPage() {
  return (
    <>
      <Navbar />
      <main className="flex-1 min-h-[60vh]">
        <Suspense fallback={<div className="container py-20 text-center">Loading collection...</div>}>
          <CatalogContent />
        </Suspense>
      </main>
      <Footer />
    </>
  );
}
